import { useState, useRef, useEffect, useCallback } from "react";

const COACH_SYSTEM = `You are an experienced cycling coach reviewing training data from aeyu.io (a Strava analytics app). You provide evidence-based, practical feedback.

WHAT YOU RECEIVE:
Data arrives in various formats — full training logs with weekly tables and zone distribution, single ride exports with segment efforts and awards, segment history with progression, or casual text descriptions. Work with whatever you get.

HOW TO READ THE DATA:
- A large gap between moving time and elapsed time usually means a group ride with stops — interpret the ride accordingly
- "Normalized power >> average power" (high variability index) on a group ride is expected, not a pacing flaw
- Segment awards (year-bests, PRs, top-decile) are achievements worth acknowledging
- Performance Capacity trends reflect recent load — a negative trend after hard days is normal physiology, not necessarily a red flag
- If data is sparse, say what you can see and note what would help — don't over-interpret

ANALYSIS STRUCTURE:
1. Start with what stands out positively — strong efforts, achievements, good patterns
2. Put the ride/period in context (training load, consistency, ride type)
3. Note areas for improvement with specific, actionable suggestions
4. When something is ambiguous (training intent, fatigue level), ask rather than assert

COACHING PRINCIPLES:
- Polarized model: ~80% easy (Z1-Z2), ~20% hard (Z4+). Z3 is the gray zone.
- Group rides are a valid training modality. Riders deliberately race key segments (climbs, sprints), then regroup and recover between. High NP:AP ratio, segment-by-segment surging, and stops between efforts are the format — don't misread this as poor pacing
- Masters athletes (40+): recovery matters more, consistency over peak load
- Max 2-3 high-intensity sessions per week, but define "intensity" honestly — a group ride with surges counts
- Progressive overload: ≤10% weekly volume increase
- Consistency streaks are worth protecting

TONE:
- Use imperial units (miles, feet, mph, lbs) in your responses, converting from metric data as needed
- Coach, not critic. You're helping someone who's already out there riding.
- Specific over general — reference actual numbers from the data
- Measured confidence. You're seeing a snapshot, not the full picture. A stateless coach should be appropriately humble about what it doesn't know.
- Genuine praise for genuine achievements. Don't manufacture it, but don't withhold it either.
- When recommending changes, frame them as "consider" or "you might try" rather than demands
- End with 1-3 concrete suggestions`;

function renderCoachText(text) {
  if (!text) return null;
  return text.split("\n").map((line, i) => {
    if (line.startsWith("### ")) return <h4 key={i} style={{ fontSize: 14, fontWeight: 600, color: "#1A1610", margin: "14px 0 4px" }}>{line.slice(4)}</h4>;
    if (line.startsWith("## ")) return <h3 key={i} style={{ fontSize: 15, fontFamily: "var(--f-serif)", color: "#5C5548", margin: "16px 0 6px" }}>{line.slice(3)}</h3>;
    if (line.startsWith("# ")) return <h2 key={i} style={{ fontSize: 18, fontFamily: "var(--f-serif)", color: "#1A1610", margin: "20px 0 8px" }}>{line.slice(2)}</h2>;
    if (line.startsWith("- ") || line.startsWith("* ")) return <div key={i} style={{ paddingLeft: 16, margin: "3px 0", lineHeight: 1.5 }}>• {boldify(line.slice(2))}</div>;
    if (line.trim() === "") return <div key={i} style={{ height: 8 }} />;
    return <p key={i} style={{ margin: "4px 0", lineHeight: 1.6 }}>{boldify(line)}</p>;
  });
}

function boldify(text) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((p, i) =>
    p.startsWith("**") && p.endsWith("**")
      ? <strong key={i} style={{ color: "#1A1610" }}>{p.slice(2, -2)}</strong>
      : p
  );
}

function detectExportType(text) {
  if (!text) return "unknown";
  if (text.includes("export_type") && text.includes("single_ride")) return "ride";
  if (text.includes("# Ride:")) return "ride";
  if (text.includes("# Segment:")) return "segment";
  if (text.includes("# Cycling Training Data")) return "training";
  if (text.includes("Weekly Volume") || text.includes("weekly_rollups")) return "training";
  if (text.includes("Segment Efforts") || text.includes("segment_efforts")) return "ride";
  if (text.includes("All Efforts") && text.includes("Grade")) return "segment";
  return "general";
}

function exportTypeLabel(type) {
  return { ride: "Ride Analysis", segment: "Segment History", training: "Training Log", general: "Cycling Data" }[type] || "Data";
}

export default function BikeCoach() {
  const [phase, setPhase] = useState("landing");
  const [pastedData, setPastedData] = useState("");
  const [messages, setMessages] = useState([]);
  const [streaming, setStreaming] = useState(false);
  const [followUp, setFollowUp] = useState("");
  const [error, setError] = useState(null);
  const scrollRef = useRef(null);
  const inputRef = useRef(null);
  const textareaRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, streaming]);

  useEffect(() => {
    if (phase === "coaching" && !streaming && inputRef.current) inputRef.current.focus();
  }, [phase, streaming]);

  useEffect(() => {
    if (phase === "landing" && textareaRef.current) textareaRef.current.focus();
  }, [phase]);

  const callClaude = useCallback(async (userMsgs) => {
    setStreaming(true);
    setError(null);
    try {
      const resp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 2000,
          system: COACH_SYSTEM,
          messages: userMsgs,
        }),
      });
      if (!resp.ok) throw new Error(`API ${resp.status}: ${(await resp.text()).slice(0, 200)}`);
      const data = await resp.json();
      return data.content.map(b => b.type === "text" ? b.text : "").join("");
    } catch (e) {
      setError(e.message);
      return null;
    } finally {
      setStreaming(false);
    }
  }, []);

  const handleAnalyze = useCallback(async (data) => {
    const text = data || pastedData;
    if (!text.trim()) return;
    const type = detectExportType(text);
    const prompts = {
      ride: "Here's my ride data from aeyu.io. What do you see?",
      segment: "Here's my segment history from aeyu.io. How's my progression?",
      training: "Here's my training log from aeyu.io. How does my recent training look?",
      general: "Here's my cycling data. What do you see?",
    };
    const prompt = `${prompts[type] || prompts.general}\n\n${text}`;
    const userMsgs = [{ role: "user", content: prompt }];
    const chars = text.length;
    const lines = text.split("\n").length;
    setMessages([{ role: "user", label: exportTypeLabel(type), summary: `${chars.toLocaleString()} chars · ${lines} lines` }]);
    setPhase("coaching");
    const reply = await callClaude(userMsgs);
    if (reply) setMessages(prev => [...prev, { role: "assistant", content: reply, apiMessages: userMsgs }]);
  }, [pastedData, callClaude]);

  const handleFollowUp = useCallback(async () => {
    if (!followUp.trim() || streaming) return;
    const lastAssistant = [...messages].reverse().find(m => m.role === "assistant");
    const prevApiMsgs = lastAssistant?.apiMessages || [{ role: "user", content: pastedData }];
    const fullHistory = [
      ...prevApiMsgs,
      ...(lastAssistant ? [{ role: "assistant", content: lastAssistant.content }] : []),
      { role: "user", content: followUp },
    ];
    setMessages(prev => [...prev, { role: "user", content: followUp }]);
    setFollowUp("");
    const reply = await callClaude(fullHistory);
    if (reply) setMessages(prev => [...prev, { role: "assistant", content: reply, apiMessages: fullHistory.slice(0, -1) }]);
  }, [followUp, streaming, messages, pastedData, callClaude]);

  const css = `
    @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&family=Instrument+Serif&display=swap');
    :root {
      --f-serif: 'Instrument Serif', Georgia, serif;
      --f-sans: 'DM Sans', system-ui, sans-serif;
      --f-mono: 'IBM Plex Mono', monospace;
      --c-paper: #F6F3EE;
      --c-card: #FFFFFF;
      --c-text: #1A1610;
      --c-muted: #5C5548;
      --c-faint: #8C8374;
      --c-border: #D4CFC7;
      --c-terracotta: #B85A28;
      --c-strava: #FC4C02;
      --c-hover: #E5430A;
      --c-tag-bg: #F0EBE3;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
  `;

  const S = {
    root: { fontFamily: "var(--f-sans)", background: "var(--c-paper)", minHeight: "100vh", color: "var(--c-text)", fontSize: 14, lineHeight: 1.5 },
    container: { maxWidth: 640, margin: "0 auto", padding: "24px 16px" },
    card: { background: "var(--c-card)", borderRadius: 12, padding: "20px 24px", marginBottom: 16, boxShadow: "0 1px 3px rgba(26,22,16,0.06)" },
    muted: { color: "var(--c-muted)" },
    faint: { color: "var(--c-faint)", fontSize: 12 },
    mono: { fontFamily: "var(--f-mono)", fontSize: 12 },
    cta: { background: "var(--c-strava)", color: "#fff", border: "none", borderRadius: 8, padding: "14px 24px", fontSize: 16, fontWeight: 600, cursor: "pointer", fontFamily: "var(--f-sans)", width: "100%" },
    textarea: { width: "100%", minHeight: 160, border: "1.5px solid var(--c-border)", borderRadius: 8, padding: 12, fontSize: 13, fontFamily: "var(--f-mono)", background: "#FAFAF8", color: "var(--c-text)", resize: "vertical", outline: "none", boxSizing: "border-box", lineHeight: 1.4 },
    input: { flex: 1, border: "1.5px solid var(--c-border)", borderRadius: 8, padding: "10px 12px", fontSize: 14, fontFamily: "var(--f-sans)", background: "#fff", color: "var(--c-text)", outline: "none" },
    tag: { display: "inline-block", background: "var(--c-tag-bg)", color: "var(--c-muted)", borderRadius: 4, padding: "2px 8px", fontSize: 11, fontWeight: 600, marginRight: 6 },
  };

  if (phase === "landing") {
    const detected = pastedData.trim() ? detectExportType(pastedData) : null;
    return (
      <div style={S.root}>
        <style>{css}</style>
        <div style={S.container}>
          <div style={{ textAlign: "center", marginBottom: 28, position: "relative" }}>
            <svg viewBox="0 0 640 60" style={{ position: "absolute", top: -10, left: -16, right: -16, width: "calc(100% + 32px)", height: 60, opacity: 0.04, pointerEvents: "none" }}>
              <path d="M0 40 C80 35 160 25 240 30 C320 35 400 20 480 25 C560 30 600 22 640 28" fill="none" stroke="#B85A28" strokeWidth="1.5"/>
              <path d="M0 50 C100 42 200 38 300 44 C400 50 500 35 640 42" fill="none" stroke="#B85A28" strokeWidth="1"/>
              <path d="M0 30 C120 22 240 32 360 26 C480 20 560 28 640 24" fill="none" stroke="#B85A28" strokeWidth="1"/>
            </svg>
            <div style={{ marginBottom: 12 }}>
              <span style={{ fontFamily: "var(--f-serif)", fontSize: 28, fontWeight: 400, color: "var(--c-text)", letterSpacing: "-0.01em" }}>
                aeyu<span style={{ color: "var(--c-terracotta)" }}>.io</span>
              </span>
            </div>
            <div style={{ width: 40, height: 2, background: "var(--c-terracotta)", margin: "0 auto 12px", borderRadius: 1, opacity: 0.6 }} />
            <h1 style={{ fontFamily: "var(--f-serif)", fontSize: 32, fontWeight: 400, margin: "0 0 6px" }}>AI Bike Coach</h1>
            <div style={{ color: "var(--c-faint)", fontSize: 13, fontStyle: "italic" }}>
              It's just you and your efforts
            </div>
          </div>

          <div style={S.card}>
            {detected && (
              <div style={{ marginBottom: 10 }}>
                <span style={{ ...S.mono, color: "var(--c-terracotta)" }}>{exportTypeLabel(detected)}</span>
              </div>
            )}
            <textarea
              ref={textareaRef}
              style={S.textarea}
              placeholder={"Paste your ride data here (⌘V / Ctrl+V)\n\nCopied from aeyu.io → Coach with Claude?\nJust paste — it's already on your clipboard."}
              value={pastedData}
              onChange={e => setPastedData(e.target.value)}
              onFocus={e => e.target.style.borderColor = "var(--c-terracotta)"}
              onBlur={e => e.target.style.borderColor = "var(--c-border)"}
            />
            {pastedData.trim() && (
              <div style={{ ...S.faint, ...S.mono, margin: "6px 0 12px" }}>
                {pastedData.length.toLocaleString()} chars · {pastedData.split("\n").length} lines
              </div>
            )}
            <button
              style={{ ...S.cta, ...(pastedData.trim() ? {} : { background: "var(--c-border)", color: "var(--c-faint)", cursor: "not-allowed" }) }}
              disabled={!pastedData.trim()}
              onClick={() => handleAnalyze()}
              onMouseEnter={e => { if (pastedData.trim()) e.target.style.background = "var(--c-hover)"; }}
              onMouseLeave={e => { if (pastedData.trim()) e.target.style.background = "var(--c-strava)"; }}
            >
              Analyze
            </button>
          </div>

          <div style={{ ...S.card, background: "transparent", boxShadow: "none", border: "1px dashed var(--c-border)", padding: "16px 20px" }}>
            <h2 style={{ fontFamily: "var(--f-serif)", fontSize: 15, margin: "0 0 8px" }}>New here?</h2>
            <div style={{ ...S.muted, fontSize: 13, lineHeight: 1.6 }}>
              <a href="https://aeyu.io" target="_blank" rel="noopener" style={{ color: "var(--c-terracotta)", textDecoration: "none", fontWeight: 600, borderBottom: "1px solid rgba(184,90,40,0.3)" }}>aeyu.io</a>
              {" "}connects to your Strava and gives every ride the recognition it deserves. Use{" "}
              <strong>Coach with Claude →</strong> on any ride to copy your data and land here. Or paste anything — training logs, single rides, segment histories.
            </div>
          </div>

          {error && (
            <div style={{ ...S.card, borderLeft: "3px solid #dc3545", marginTop: 8 }}>
              <div style={{ color: "#dc3545", fontSize: 13 }}>{error}</div>
            </div>
          )}

          <div style={{ ...S.faint, textAlign: "center", marginTop: 8, lineHeight: 1.8 }}>
            Stateless · Nothing stored · Data stays in this conversation
            <br />
            <a href="https://aeyu.io" target="_blank" rel="noopener" style={{ color: "var(--c-terracotta)", textDecoration: "none", fontSize: 11 }}>aeyu.io</a>
            <span style={{ margin: "0 6px", color: "var(--c-border)" }}>·</span>
            <span style={{ fontSize: 11 }}>Powered by Strava</span>
            <span style={{ margin: "0 6px", color: "var(--c-border)" }}>·</span>
            <span style={{ fontSize: 11 }}>Analysis by Claude</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={S.root}>
      <style>{css}</style>
      <div style={S.container}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 16 }}>
          <h1 style={{ fontFamily: "var(--f-serif)", fontSize: 22, fontWeight: 400, margin: 0 }}>
              <span style={{ fontFamily: "var(--f-serif)", fontSize: 16, color: "var(--c-faint)", marginRight: 8 }}>aeyu<span style={{ color: "var(--c-terracotta)" }}>.io</span></span>
              AI Bike Coach
            </h1>
          <button
            onClick={() => { setPhase("landing"); setMessages([]); setPastedData(""); setError(null); }}
            style={{ background: "none", border: "none", color: "var(--c-terracotta)", cursor: "pointer", fontSize: 13, fontFamily: "var(--f-sans)" }}
          >
            ← New analysis
          </button>
        </div>

        <div ref={scrollRef} style={{ marginBottom: 16 }}>
          {messages.map((msg, i) => (
            <div key={i} style={S.card}>
              {msg.role === "user" && !msg.content && (
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <div style={{ width: 6, height: 6, borderRadius: 3, background: "var(--c-terracotta)", flexShrink: 0 }} />
                  <span style={{ ...S.muted, fontWeight: 600, fontSize: 13 }}>{msg.label}</span>
                  {msg.summary && <span style={S.faint}>{msg.summary}</span>}
                </div>
              )}
              {msg.role === "user" && msg.content && (
                <div style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
                  <div style={{ width: 6, height: 6, borderRadius: 3, background: "var(--c-terracotta)", flexShrink: 0, marginTop: 6 }} />
                  <span style={{ ...S.muted, fontSize: 14 }}>{msg.content}</span>
                </div>
              )}
              {msg.role === "assistant" && (
                <div style={S.muted}>{renderCoachText(msg.content)}</div>
              )}
            </div>
          ))}

          {streaming && (
            <div style={S.card}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, ...S.muted }}>
                <div style={{ width: 8, height: 8, borderRadius: 4, background: "var(--c-terracotta)", animation: "pulse 1.2s ease-in-out infinite" }} />
                <span style={{ fontSize: 13 }}>Analyzing...</span>
              </div>
            </div>
          )}

          {error && (
            <div style={{ ...S.card, borderLeft: "3px solid #dc3545" }}>
              <div style={{ color: "#dc3545", fontSize: 13 }}>{error}</div>
            </div>
          )}
        </div>

        {messages.some(m => m.role === "assistant") && !streaming && (
          <div style={{ display: "flex", gap: 8, position: "sticky", bottom: 0, background: "var(--c-paper)", padding: "12px 0" }}>
            <input
              ref={inputRef}
              style={S.input}
              placeholder="Ask a follow-up..."
              value={followUp}
              onChange={e => setFollowUp(e.target.value)}
              onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleFollowUp(); } }}
              onFocus={e => e.target.style.borderColor = "var(--c-terracotta)"}
              onBlur={e => e.target.style.borderColor = "var(--c-border)"}
            />
            <button
              style={{ background: "var(--c-terracotta)", color: "#fff", border: "none", borderRadius: 8, padding: "10px 16px", fontSize: 14, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap", opacity: followUp.trim() ? 1 : 0.5 }}
              disabled={!followUp.trim()}
              onClick={handleFollowUp}
            >
              Ask
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

<<<END>>>

